-- 15 dummy accounts for sale. Run after setup.sql, in the Supabase SQL editor.
-- Needs at least one SELLER account (role seller or both). An admin account does not count.
-- By default the listings are shared round-robin between every active seller you have.
-- To give them all to one seller, put that seller's email below. Safe to run twice.
-- To remove them again:  delete from public.listings where id between 'CM-49001' and 'CM-49015';

do $$
declare
  seller_email text := '';   -- optional, e.g. 'seller@example.com'
  sellers uuid[];
begin
  if seller_email <> '' then
    select array_agg(p.id) into sellers
      from public.profiles p join auth.users u on u.id = p.id
     where u.email = seller_email and p.role in ('seller', 'both') and p.status = 'active';
  else
    select array_agg(p.id order by p.created_at) into sellers
      from public.profiles p where p.role in ('seller', 'both') and p.status = 'active';
  end if;

  if sellers is null then
    raise exception 'No active seller found. Register an account on the site and choose Seller (an admin account does not count), then run this again.';
  end if;

  -- Dev convenience: show these sellers as verified with a rating, so the listings look complete.
  update public.profiles
     set seller_verification = 'verified', seller_rating = coalesce(seller_rating, 4.8)
   where id = any(sellers) and seller_verification <> 'verified';

  insert into public.listings (
    id, slug, title, status, seller_id, featured, views, favorites,
    region, platform, game_version, level, mp_rank, mp_ranked_season, br_rank,
    inventory, cp, credits, access, proof_provided, proof_redacted, media,
    price_cents, previous_price_cents, currency, buyer_fee_pct, risk,
    verification_status, moderation_notes, reviewed_at, created_at
  )
  select
    v.id, v.slug, v.title, 'active', sellers[1 + ((v.n - 1) % array_length(sellers, 1))], v.featured, v.views, v.favs,
    v.region, v.platform, v.ver, v.level, v.mp, v.season, v.br,
    v.inventory::jsonb, v.cp, v.credits,
    jsonb_build_object(
      'signInMethod', v.sign_in,
      'transferLimitations', 'Linked sign-in must be changed by the buyer after delivery. Some regions limit changes.',
      'recoveryDependencies', v.recovery),
    v.proof, true,
    jsonb_build_array(
      jsonb_build_object('src', '/listings/' || v.id || '/profile.jpg', 'caption', 'Profile and level'),
      jsonb_build_object('src', '/listings/' || v.id || '/ranks.jpg', 'caption', 'Multiplayer and battle royale ranks'),
      jsonb_build_object('src', '/listings/' || v.id || '/inventory.jpg', 'caption', 'Inventory')),
    v.price, v.was, 'USD', 5,
    jsonb_build_object(
      'knownRestrictions', v.restrictions,
      'previousEnforcement', v.enforcement,
      'transferUncertainty', 'Account transfers are not recognised by the game publisher. Access may be restricted or recovered by the original owner at any time.'),
    case when v.verified then 'attributes_verified' else 'seller_declared' end,
    v.notes, v.created::timestamptz, v.created::timestamptz
  from (values
      (1, 'CM-49001', 'level-238-legendary-rank-7-mythic-items', 'Level 238, Legendary rank, 7 mythic items', true, 530, 61, 'Global', 'Android', 'Season 10, 2026', 238, 'Legendary', 'Season 10', 'Grandmaster', '{"mythic": ["Kilo Bolt-Action Ashfall", "Oden Eclipse", "HVK-30 Quartz", "DL Q33 Cryo Fang", "BP50 Inferno", "Fennec Redline", "ASM10 Voidwalker"], "legendary": ["AK-47 Jungle Wrath", "Fennec Ember", "QQ9 Riptide", "CBR4 Mirage", "Oden Night Watch", "ASM10 Tangent", "DR-H Tundra", "Switchblade X9 Pulse", "Man-O-War Ironclad", "M4 Frostbite", "BK57 Dusk", "RUS-79U Static", "Chopper Flatline", "LK24 Slate"], "operatorSkins": ["Ghost Nightfall", "Nikto Chrome", "Alex Rustwater", "Park Silverline", "Price Winter Guard"], "weapons": [{"name": "Kilo Bolt-Action", "skin": "Ashfall", "rarity": "Mythic", "upgradeLevel": 5}, {"name": "Oden", "skin": "Eclipse", "rarity": "Mythic", "upgradeLevel": 4}, {"name": "HVK-30", "skin": "Quartz", "rarity": "Mythic", "upgradeLevel": 5}], "collectibles": {"emotes": 39, "callingCards": 119, "avatars": 29, "frames": 17, "charms": 23, "blueprints": 9}}', 1120, 71000, 'Activision account', 'Seller''s email, to be removed before delivery', true, 48000, 52000, 'None known', 'None disclosed', true, 'Level, ranks and items matched screenshots.', '2026-11-02'),
